def is_palindrome(s):
    cleaned = ''.join(c for c in s.lower() if c.isalnum())
    return cleaned == cleaned[::-1]

def average(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

import string

def most_common_word(text):
    words = text.lower().split()

    word_counts = {}
    first_appearance = {}

    for i, word in enumerate(words):
        cleaned = word.strip(string.punctuation)

        if cleaned:
            if cleaned not in first_appearance:
                first_appearance[cleaned] = i
            word_counts[cleaned] = word_counts.get(cleaned, 0) + 1

    if not word_counts:
        return None

    most_common = max(word_counts.keys(), key=lambda w: (word_counts[w], -first_appearance[w]))
    return most_common
